// Go source emitter for ai/models_generated.go. The generated file is package
// ai (same package as the ai.Model / compat types), so the emitter references
// package-ai names directly; lo.ToPtr provides the *T pointer literals the
// generated compat fields need. Output is run through go/format.
package main

import (
	"fmt"
	"go/format"
	"math"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/ZoroSpace/pig/ai"
)

// generateModelsFile renders ai/models_generated.go from the deduplicated,
// sorted provider catalog.
func generateModelsFile(providers map[ai.ProviderID]map[string]*ai.Model, generatedAt int64) ([]byte, error) {
	var b strings.Builder

	b.WriteString("// This file is generated by ai/scripts/generatemodels (pi: scripts/generate-models.ts).\n")
	b.WriteString("// Do not edit manually.\n\n")

	b.WriteString("package ai\n\n")
	b.WriteString("import \"github.com/samber/lo\"\n\n")

	b.WriteString("// MODELS is the generated built-in catalog (pi: models.generated.ts MODELS):\n")
	b.WriteString("// provider id -> model id -> model. pi types the key set closed (keyof\n")
	b.WriteString("// typeof MODELS); pig keys by the open ProviderID. pi's per-provider\n")
	b.WriteString("// providers/*.models.ts files have no separate Go counterpart — the\n")
	b.WriteString("// generator emits one file.\n")
	b.WriteString("var MODELS = map[ProviderID]map[string]Model{\n")

	providerIDs := make([]string, 0, len(providers))
	for providerID := range providers {
		providerIDs = append(providerIDs, string(providerID))
	}
	sort.Strings(providerIDs)

	for _, providerID := range providerIDs {
		models := providers[ai.ProviderID(providerID)]
		ids := make([]string, 0, len(models))
		for id := range models {
			ids = append(ids, id)
		}
		sort.Strings(ids)

		b.WriteString("\t")
		b.WriteString(providerConstName(ai.ProviderID(providerID)))
		b.WriteString(": {\n")
		for _, id := range ids {
			b.WriteString("\t\t")
			b.WriteString(strconv.Quote(id))
			b.WriteString(": {\n")
			writeModel(&b, models[id], "\t\t\t")
			b.WriteString("\t\t},\n")
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n\n")

	b.WriteString("// MODELSGeneratedAt is the generation timestamp shared by all built-in\n")
	b.WriteString("// provider catalogs, Unix milliseconds (pi: providers/data/.manifest.json\n")
	b.WriteString("// generatedAt). 0 means unknown; pi models the unknown case as undefined.\n")
	fmt.Fprintf(&b, "var MODELSGeneratedAt int64 = %d\n", generatedAt)

	src := b.String()
	formatted, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("format generated source: %w\n---\n%s", err, src)
	}
	return formatted, nil
}

func writeField(b *strings.Builder, indent, name, value string) {
	b.WriteString(indent)
	b.WriteString(name)
	b.WriteString(": ")
	b.WriteString(value)
	b.WriteString(",\n")
}

// writeModel emits one Model composite literal (field order follows ai.Model).
func writeModel(b *strings.Builder, model *ai.Model, indent string) {
	writeField(b, indent, "ID", strconv.Quote(model.ID))
	writeField(b, indent, "Name", strconv.Quote(model.Name))
	writeField(b, indent, "API", apiConstName(model.API))
	writeField(b, indent, "Provider", providerConstName(model.Provider))
	writeField(b, indent, "BaseURL", strconv.Quote(model.BaseURL))
	writeField(b, indent, "Reasoning", strconv.FormatBool(model.Reasoning))
	if model.ThinkingLevelMap != nil {
		writeThinkingLevelMap(b, model.ThinkingLevelMap, indent)
	}
	if model.Input != nil {
		writeInput(b, model.Input, indent)
	}
	writeCost(b, model.Cost, indent)
	writeField(b, indent, "ContextWindow", strconv.FormatInt(model.ContextWindow, 10))
	writeField(b, indent, "MaxTokens", strconv.FormatInt(model.MaxTokens, 10))
	if model.Headers != nil {
		writeStringMap(b, "Headers", model.Headers, indent)
	}
	if model.Compat != nil {
		writeCompat(b, model.Compat, indent)
	}
}

var thinkingLevelOrder = []ai.ModelThinkingLevel{
	ai.ModelThinkingOff, ai.ModelThinkingMinimal, ai.ModelThinkingLow,
	ai.ModelThinkingMedium, ai.ModelThinkingHigh, ai.ModelThinkingXHigh, ai.ModelThinkingMax,
}

// writeThinkingLevelMap emits a map literal; nil values mark a level as
// unsupported and must survive emission (pi: null in thinkingLevelMap).
func writeThinkingLevelMap(b *strings.Builder, m ai.ThinkingLevelMap, indent string) {
	b.WriteString(indent)
	b.WriteString("ThinkingLevelMap: ThinkingLevelMap{\n")
	inner := indent + "\t"
	for _, level := range thinkingLevelOrder {
		v, ok := m[level]
		if !ok {
			continue
		}
		if v == nil {
			b.WriteString(inner)
			b.WriteString(modelThinkingConstName(level))
			b.WriteString(": nil,\n")
		} else {
			b.WriteString(inner)
			b.WriteString(modelThinkingConstName(level))
			b.WriteString(": lo.ToPtr(")
			b.WriteString(strconv.Quote(*v))
			b.WriteString("),\n")
		}
	}
	b.WriteString(indent)
	b.WriteString("},\n")
}

func writeInput(b *strings.Builder, input []ai.ModelInput, indent string) {
	b.WriteString(indent)
	b.WriteString("Input: []ModelInput{")
	parts := make([]string, len(input))
	for i, m := range input {
		parts[i] = modelInputConstName(m)
	}
	b.WriteString(strings.Join(parts, ", "))
	b.WriteString("},\n")
}

// writeCost emits ModelCost; the common no-tier form is a single line.
func writeCost(b *strings.Builder, cost ai.ModelCost, indent string) {
	if len(cost.Tiers) == 0 {
		b.WriteString(indent)
		b.WriteString("Cost: ModelCost{ModelCostRates: ModelCostRates{")
		b.WriteString("Input: ")
		b.WriteString(floatLit(cost.Input))
		b.WriteString(", ")
		b.WriteString("Output: ")
		b.WriteString(floatLit(cost.Output))
		b.WriteString(", ")
		b.WriteString("CacheRead: ")
		b.WriteString(floatLit(cost.CacheRead))
		b.WriteString(", ")
		b.WriteString("CacheWrite: ")
		b.WriteString(floatLit(cost.CacheWrite))
		b.WriteString("}},\n")
		return
	}
	b.WriteString(indent)
	b.WriteString("Cost: ModelCost{\n")
	inner := indent + "\t"
	b.WriteString(inner)
	b.WriteString("ModelCostRates: ModelCostRates{")
	b.WriteString("Input: ")
	b.WriteString(floatLit(cost.Input))
	b.WriteString(", Output: ")
	b.WriteString(floatLit(cost.Output))
	b.WriteString(", CacheRead: ")
	b.WriteString(floatLit(cost.CacheRead))
	b.WriteString(", CacheWrite: ")
	b.WriteString(floatLit(cost.CacheWrite))
	b.WriteString("},\n")
	b.WriteString(inner)
	b.WriteString("Tiers: []ModelCostTier{\n")
	for _, tier := range cost.Tiers {
		b.WriteString(inner)
		b.WriteString("\t{ModelCostRates: ModelCostRates{")
		b.WriteString("Input: ")
		b.WriteString(floatLit(tier.Input))
		b.WriteString(", Output: ")
		b.WriteString(floatLit(tier.Output))
		b.WriteString(", CacheRead: ")
		b.WriteString(floatLit(tier.CacheRead))
		b.WriteString(", CacheWrite: ")
		b.WriteString(floatLit(tier.CacheWrite))
		fmt.Fprintf(b, "}, InputTokensAbove: %d},\n", tier.InputTokensAbove)
	}
	b.WriteString(inner)
	b.WriteString("},\n")
	b.WriteString(indent)
	b.WriteString("},\n")
}

func writeStringMap(b *strings.Builder, name string, m map[string]string, indent string) {
	b.WriteString(indent)
	b.WriteString(name)
	b.WriteString(": map[string]string{\n")
	inner := indent + "\t"
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		b.WriteString(inner)
		b.WriteString(strconv.Quote(k))
		b.WriteString(": ")
		b.WriteString(strconv.Quote(m[k]))
		b.WriteString(",\n")
	}
	b.WriteString(indent)
	b.WriteString("},\n")
}

// writeCompat emits the ModelCompat interface value as a concrete pointer
// literal.
func writeCompat(b *strings.Builder, compat ai.ModelCompat, indent string) {
	switch c := compat.(type) {
	case *ai.OpenAICompletionsCompat:
		b.WriteString(indent)
		b.WriteString("Compat: &OpenAICompletionsCompat{\n")
		writeCompatFields(b, reflect.ValueOf(c).Elem(), indent+"\t")
		b.WriteString(indent)
		b.WriteString("},\n")
	case *ai.AnthropicMessagesCompat:
		b.WriteString(indent)
		b.WriteString("Compat: &AnthropicMessagesCompat{\n")
		writeCompatFields(b, reflect.ValueOf(c).Elem(), indent+"\t")
		b.WriteString(indent)
		b.WriteString("},\n")
	case *ai.OpenAIResponsesCompat:
		b.WriteString(indent)
		b.WriteString("Compat: &OpenAIResponsesCompat{\n")
		writeCompatFields(b, reflect.ValueOf(c).Elem(), indent+"\t")
		b.WriteString(indent)
		b.WriteString("},\n")
	case *ai.BedrockCompat:
		b.WriteString(indent)
		b.WriteString("Compat: &BedrockCompat{\n")
		writeCompatFields(b, reflect.ValueOf(c).Elem(), indent+"\t")
		b.WriteString(indent)
		b.WriteString("},\n")
	default:
		panic(fmt.Sprintf("generatemodels: unsupported compat type %T", compat))
	}
}

// writeCompatFields emits the non-nil fields of a compat struct. Pointer
// fields render as lo.ToPtr(...) so the emitted value is the *T the struct
// expects; map/slice fields render directly.
func writeCompatFields(b *strings.Builder, v reflect.Value, indent string) {
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		if field.Kind() == reflect.Pointer && field.IsNil() {
			continue
		}
		if (field.Kind() == reflect.Map || field.Kind() == reflect.Slice) && field.IsNil() {
			continue
		}
		name := v.Type().Field(i).Name
		if field.Kind() == reflect.Pointer {
			b.WriteString(indent)
			b.WriteString(name)
			b.WriteString(": lo.ToPtr(")
			writeGoValue(b, field.Elem(), indent)
			b.WriteString("),\n")
			continue
		}
		b.WriteString(indent)
		b.WriteString(name)
		b.WriteString(": ")
		writeGoValue(b, field, indent)
		b.WriteString(",\n")
	}
}

// writeGoValue renders a value of any supported shape as a Go literal.
func writeGoValue(b *strings.Builder, v reflect.Value, indent string) {
	for v.Kind() == reflect.Pointer || v.Kind() == reflect.Interface {
		if v.IsNil() {
			b.WriteString("nil")
			return
		}
		v = v.Elem()
	}
	switch v.Kind() {
	case reflect.Bool:
		b.WriteString(strconv.FormatBool(v.Bool()))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Float32, reflect.Float64:
		b.WriteString(floatLit(v.Float()))
	case reflect.String:
		writeTypedString(b, v.Type(), v.String())
	case reflect.Slice:
		writeSliceValue(b, v, indent)
	case reflect.Map:
		writeMapValue(b, v, indent)
	case reflect.Struct:
		writeStructValue(b, v, indent)
	default:
		panic(fmt.Sprintf("generatemodels: unsupported value kind %s (%s)", v.Kind(), v.Type()))
	}
}

// writeTypedString quotes a string or renders a defined string type as its
// package constant (falling back to a TypeName("...") cast).
func writeTypedString(b *strings.Builder, t reflect.Type, s string) {
	if t.Kind() == reflect.String && t.Name() == "" {
		b.WriteString(strconv.Quote(s))
		return
	}
	if constName := stringConstName(t.Name(), s); constName != "" {
		b.WriteString(constName)
		return
	}
	b.WriteString(t.Name())
	b.WriteString("(")
	b.WriteString(strconv.Quote(s))
	b.WriteString(")")
}

// goTypeName returns the package-ai spelling of a type (unqualified named
// type, or String() for unnamed kinds); the generated file is package ai and
// never imports ai/types.
func goTypeName(t reflect.Type) string {
	if t.Name() != "" {
		return t.Name()
	}
	return t.String()
}

func writeSliceValue(b *strings.Builder, v reflect.Value, indent string) {
	if v.Len() == 0 {
		b.WriteString("nil")
		return
	}
	b.WriteString("[]")
	b.WriteString(goTypeName(v.Type().Elem()))
	b.WriteString("{\n")
	for i := 0; i < v.Len(); i++ {
		b.WriteString(indent)
		b.WriteString("\t")
		writeGoValue(b, v.Index(i), indent+"\t")
		b.WriteString(",\n")
	}
	b.WriteString(indent)
	b.WriteString("}")
}

func writeMapValue(b *strings.Builder, v reflect.Value, indent string) {
	keys := v.MapKeys()
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].Kind() == reflect.String {
			return keys[i].String() < keys[j].String()
		}
		return fmt.Sprintf("%v", keys[i]) < fmt.Sprintf("%v", keys[j])
	})
	b.WriteString("map[")
	b.WriteString(goTypeName(v.Type().Key()))
	b.WriteString("]")
	b.WriteString(goTypeName(v.Type().Elem()))
	b.WriteString("{\n")
	for _, k := range keys {
		b.WriteString(indent)
		b.WriteString("\t")
		writeGoValue(b, k, indent+"\t")
		b.WriteString(": ")
		writeGoValue(b, v.MapIndex(k), indent+"\t")
		b.WriteString(",\n")
	}
	b.WriteString(indent)
	b.WriteString("}")
}

// writeStructValue renders a struct literal, skipping zero scalar fields.
func writeStructValue(b *strings.Builder, v reflect.Value, indent string) {
	b.WriteString(v.Type().Name())
	b.WriteString("{\n")
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		if !field.CanInterface() {
			continue
		}
		if isZeroScalar(field) {
			continue
		}
		b.WriteString(indent)
		b.WriteString("\t")
		b.WriteString(v.Type().Field(i).Name)
		b.WriteString(": ")
		writeGoValue(b, field, indent+"\t")
		b.WriteString(",\n")
	}
	b.WriteString(indent)
	b.WriteString("}")
}

// isZeroScalar reports whether a scalar field is its zero value (skipped in
// struct literals to keep output minimal).
func isZeroScalar(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.Bool, reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Float32, reflect.Float64, reflect.String:
		return v.IsZero()
	}
	return false
}

// floatLit renders a float64 as a compact Go literal: integers print without
// exponent, others shortest-round-trip.
func floatLit(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatFloat(f, 'f', -1, 64)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func apiConstName(api ai.Api) string {
	if name, ok := apiConsts[api]; ok {
		return name
	}
	return "Api(" + strconv.Quote(string(api)) + ")"
}

func providerConstName(provider ai.ProviderID) string {
	if name, ok := providerConsts[provider]; ok {
		return name
	}
	return "ProviderID(" + strconv.Quote(string(provider)) + ")"
}

func modelInputConstName(m ai.ModelInput) string {
	if name, ok := modelInputConsts[m]; ok {
		return name
	}
	return "ModelInput(" + strconv.Quote(string(m)) + ")"
}

func modelThinkingConstName(level ai.ModelThinkingLevel) string {
	if name, ok := modelThinkingConsts[level]; ok {
		return name
	}
	return "ModelThinkingLevel(" + strconv.Quote(string(level)) + ")"
}

// stringConstName maps a defined string type + value to its package constant.
func stringConstName(typeName, value string) string {
	switch typeName {
	case "ThinkingFormat":
		return thinkingFormatConsts[value]
	case "MaxTokensField":
		return maxTokensFieldConsts[value]
	case "CacheControlFormat":
		return cacheControlConsts[value]
	case "ChatTemplateVar":
		return chatTemplateVarConsts[value]
	case "ThinkingTokenBudgetField":
		return thinkingTokenBudgetFieldConsts[value]
	case "SessionAffinityFormat":
		return sessionAffinityFormatConsts[value]
	}
	return ""
}

